foreach ($r in $repos) {
  Write-Output "=== $r"
  if (git -C $r status --porcelain) { git -C $r add -A 2>$null; git -C $r commit -q -m "windows snapshot before sync" 2>&1 | Select-Object -Last 1 }
  $before = git -C $r rev-parse HEAD
  git -C $r pull --no-rebase --no-edit 2>&1 | Select-Object -Last 3
  if (Test-Path "$r\.git\MERGE_HEAD") { Write-Output "CONFLICT:"; git -C $r diff --name-only --diff-filter=U }
  $n = git -C $r rev-list --count "$before..HEAD"
  Write-Output "incoming commits: $n"
  if ($n -gt 0) { git -C $r log -1 --format="newest: %h %s (%cr)" }
  git -C $r push 2>&1 | Select-Object -Last 1
}

