$root = "C:\Users\eric_rash\Desktop\DEV"
$skip = @('.claude','_tools','_DRIVE','token-dashboard')
$dirs = @()
foreach ($p in @($root, "$root\Football", "$root\SpecialRequests")) {
  if (Test-Path $p) { $dirs += Get-ChildItem $p -Directory -Force | Where-Object { $skip -notcontains $_.Name -and $_.Name -notlike '*_OLD_merged*' -and $_.Name -notlike '.*' } }
}
$out = foreach ($d in $dirs) {
  $f = $d.FullName
  if ($f -eq "$root\Football" -or $f -eq "$root\SpecialRequests") { if (-not (Test-Path "$f\.git")) { continue } }
  if (-not (Test-Path "$f\.git")) { [pscustomobject]@{Path=$f.Replace("$root\",'');State='NOT-REPO';Dirty=0;Ahead='';Remote=''}; continue }
  $remote = git -C $f remote get-url origin 2>$null
  $dirty = @(git -C $f status --porcelain 2>$null).Count
  $ahead = if ($remote) { git -C $f rev-list --count '@{u}..HEAD' 2>$null } else { '' }
  $state = if (-not $remote) {'NO-REMOTE'} elseif ($remote -notmatch 'erash11') {'OTHER-REMOTE'} else {'ok'}
  [pscustomobject]@{Path=$f.Replace("$root\",'');State=$state;Dirty=$dirty;Ahead=$ahead;Remote=$remote}
}
$out | Export-Csv "$env:CLAUDE_JOB_DIR\tmp\inv.csv" -NoTypeInformation
"total: $($out.Count)"
$out | Where-Object { $_.State -ne 'ok' -or $_.Dirty -gt 0 -or ($_.Ahead -ne '0' -and $_.Ahead -ne '') } | Format-Table Path,State,Dirty,Ahead -AutoSize | Out-String -Width 200

